CREATE OR REPLACE FUNCTION private.data_export_policy_binding()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare p private.retention_policy_sets; m jsonb; d jsonb; c jsonb; seen text[]:='{}'; f jsonb; fields text[]; refs jsonb; privacy private.legal_document_versions; v_now timestamptz:=clock_timestamp();
begin
 select * into p from private.retention_policy_sets where retired_at is null and effective_at<=v_now;
 if not found then return null; end if;
 m:=p.export_delivery;
 if jsonb_typeof(m) is distinct from 'object' or m-ARRAY['schemaVersion','projectionVersion','projectionSha256','privacyDocumentId','privacyContentSha256','contentSha256','artifactLifetimeSeconds','snapshotLifetimeSeconds','downloadLifetimeSeconds','cleanupMode','snapshotCleanupMode','datasets']<>'{}'::jsonb
 or not(m ?& ARRAY['schemaVersion','projectionVersion','projectionSha256','privacyDocumentId','privacyContentSha256','contentSha256','artifactLifetimeSeconds','snapshotLifetimeSeconds','downloadLifetimeSeconds','cleanupMode','snapshotCleanupMode','datasets'])
 or m->>'schemaVersion' is distinct from 'USKOCI_EXPORT_DELIVERY_V2' or m->>'projectionVersion' is distinct from 'OWN_ACCOUNT_V5_11'
 or jsonb_typeof(m->'projectionSha256') is distinct from 'string' or coalesce(m->>'projectionSha256','')!~'^[a-f0-9]{64}$'
 or m->>'projectionSha256' is distinct from private.data_export_projection_sha_v5()
 or m->>'cleanupMode' is distinct from 'DELETE_EXPORT_COPY' or m->>'snapshotCleanupMode' is distinct from 'DELETE_TEMP_SNAPSHOT'
 or coalesce(m->>'privacyDocumentId','')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
 or coalesce(m->>'privacyContentSha256','')!~'^[0-9a-f]{64}$' or coalesce(m->>'contentSha256','')!~'^[0-9a-f]{64}$'
 or m->>'contentSha256' is distinct from encode(extensions.digest(convert_to((m-'contentSha256')::text,'UTF8'),'sha256'),'hex') then return null; end if;
 foreach fields slice 1 in array ARRAY[ARRAY['artifactLifetimeSeconds','2592000'],ARRAY['snapshotLifetimeSeconds','2592000'],ARRAY['downloadLifetimeSeconds','900']] loop
   if jsonb_typeof(m->fields[1]) is distinct from 'number' or (m->>fields[1])!~'^[1-9][0-9]*$' or (m->>fields[1])::numeric>(fields[2])::numeric then return null; end if;
 end loop;
 if (m->>'downloadLifetimeSeconds')::integer>(m->>'artifactLifetimeSeconds')::integer then return null; end if;
 select * into privacy from private.legal_document_versions where id=(m->>'privacyDocumentId')::uuid and document_kind='PRIVACY' and is_active and retired_at is null and effective_at<=v_now and content_sha256=m->>'privacyContentSha256';
 if not found then return null; end if;
 if exists(select 1 from private.retention_data_classes dc where dc.active and dc.required and (not exists(select 1 from private.retention_policy_rules r where r.policy_id=p.id and r.data_class=dc.code) or not exists(select 1 from jsonb_array_elements(private.data_export_dataset_catalog()) v where v->>'dataClass'=dc.code))) then return null; end if;
 if jsonb_typeof(m->'datasets') is distinct from 'array' or jsonb_array_length(m->'datasets')<>73 then return null; end if;
 for d in select value from jsonb_array_elements(m->'datasets') loop
   if jsonb_typeof(d) is distinct from 'object' or jsonb_typeof(d->'key') is distinct from 'string' or d->>'key'=any(seen) then return null; end if;
   select value into c from jsonb_array_elements(private.data_export_dataset_catalog()) where value->>'key'=d->>'key';
   if not found then return null; end if;seen:=array_append(seen,d->>'key');
   if d->>'mode'='EXCLUDE' then
     if d-ARRAY['key','mode','reasonCode']<>'{}'::jsonb or not(d ?& ARRAY['key','mode','reasonCode']) or jsonb_typeof(d->'reasonCode') is distinct from 'string' or d->>'reasonCode'!~'^[A-Z][A-Z0-9_]{0,63}$' or d->>'key'='account' then return null; end if;
   elsif d->>'mode'='INCLUDE' then
     if d-ARRAY['key','mode','fields']<>'{}'::jsonb or not(d ?& ARRAY['key','mode','fields']) or jsonb_typeof(d->'fields') is distinct from 'array' then return null; end if;
     if jsonb_array_length(d->'fields')<1 or jsonb_array_length(d->'fields')>64 then return null; end if;fields:='{}';
     for f in select value from jsonb_array_elements(d->'fields') loop
       if jsonb_typeof(f)<>'string' or not((c->'fields') ? (f#>>'{}')) or f#>>'{}'=any(fields) then return null; end if; fields:=array_append(fields,f#>>'{}');
     end loop;
     if d->>'key'='account' and not('id'=any(fields)) then return null; end if;
     if d->>'key' in('mediaMetadata','ownedMediaAssets','ownAgreementPhotos','ownAgreementVoice','ownSupportEvidence') and not('bytesIncluded'=any(fields)) then return null; end if;
   else return null; end if;
 end loop;
 select coalesce(jsonb_agg(to_jsonb(r) order by data_class),'[]'::jsonb) into refs from private.retention_policy_rules r where policy_id=p.id;
 return jsonb_build_object('policyId',p.id,'policyVersion',p.policy_version,'privacyDocumentId',privacy.id,'privacyContentSha256',privacy.content_sha256,'delivery',m,
 'sha256',encode(extensions.digest(convert_to(jsonb_build_object('policy',to_jsonb(p),'rules',refs,'privacy',to_jsonb(privacy),'catalog',private.data_export_dataset_catalog())::text,'UTF8'),'sha256'),'hex'));
exception when data_exception then return null;
end $function$

CREATE OR REPLACE FUNCTION private.need_candidate_states_v5(p_need_id uuid)
 RETURNS TABLE(response_id uuid, candidate_state text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  n public.needs; c record; remaining integer; s timestamptz; e timestamptz; eligible boolean;
begin
  select * into n from public.needs where id=p_need_id;
  if not found then return; end if;
  remaining:=greatest(n.required_slots-public.fn_need_covered_slots(n.id),0);
  for c in
    select r.id,r.worker_profile_id,r.worker_account_id,r.status,r.current_version,r.covered_slots,
      r.submitted_against_need_revision,v.need_revision as version_revision,v.content_hash,v.price_rsd as version_price,
      v.covered_slots as version_slots, v.proposed_start_at as version_start, v.proposed_end_at as version_end,
      p.account_id as profile_account, p.kind, p.profile_status, p.display_name, p.city, p.skills, p.team_capacity,
      exists(select 1 from public.agreements a where a.selected_response_id=r.id and a.status<>'CANCELLED') as has_agreement
    from public.marketplace_responses r
    left join public.marketplace_response_versions v on v.response_id=r.id and v.version=r.current_version
    left join public.app_profiles p on p.id=r.worker_profile_id
    where r.need_id=n.id and r.status<>'DRAFT'
  loop
    response_id:=c.id;
    candidate_state:=case
      when c.has_agreement or c.status='SELECTED' then 'SELECTED'
      when c.status='WITHDRAWN' then 'WITHDRAWN'
      when c.status in ('NOT_SELECTED','EXPIRED') then 'CLOSED'
      when n.status not in ('PUBLISHED','SELECTION')
        or not private.need_search_time_admitted_v1(n.id,statement_timestamp())
        or (n.response_deadline is not null and n.response_deadline<=statement_timestamp())
         or (n.schedule_kind='FIXED_WINDOW' and n.ends_at is null
           and n.starts_at is not null and n.starts_at<=statement_timestamp()) then 'CLOSED'
      when c.kind is distinct from 'WORKER' or c.profile_account is distinct from c.worker_account_id
        or c.profile_status is distinct from 'ACTIVE'
        or char_length(btrim(coalesce(c.display_name,'')))<2
        or char_length(btrim(coalesce(c.city,'')))<2
        or cardinality(coalesce(c.skills,'{}'::text[]))<1
        or c.version_slots is null
        or c.status in ('STALE','STALE_REVIEW_REQUIRED') or c.current_version is null or c.content_hash is null
        or c.version_revision is distinct from n.revision
        or c.submitted_against_need_revision is distinct from n.revision then 'STALE'
      when remaining<=0 then 'FULL'
      when c.covered_slots>remaining or c.version_slots>remaining then 'OVERFILL'
      when c.status in ('SUBMITTED','DELIVERED','VIEWED','SHORTLISTED') then 'SELECTABLE'
      else 'CLOSED' end;
    if candidate_state='SELECTABLE' then
      s:=coalesce(c.version_start,case when n.schedule_kind='FIXED_WINDOW' then n.starts_at end);
      e:=coalesce(c.version_end,case when n.schedule_kind='FIXED_WINDOW' then n.ends_at end);
      -- No proposed interval and a start-only task: revalidate the worker's
      -- confirmed service/area/instant, not a fabricated calendar duration.
      if n.schedule_kind='FIXED_WINDOW' and n.ends_at is null
         and c.version_start is null and c.version_end is null then
        s:=null; e:=null;
      end if;
      if (c.version_start is null)<>(c.version_end is null)
        or (s is null)<>(e is null)
        or (s is not null and (not isfinite(s) or not isfinite(e) or s>=e))
        or (c.version_start is null and n.schedule_kind='FIXED_WINDOW'
          and (n.starts_at is null or not isfinite(n.starts_at)
            or (n.ends_at is not null and (s is null or e is null)))) then
        candidate_state:='STALE';
      else
        eligible:=coalesce((private.match_detail_for_calendar_interval(n.id,c.worker_profile_id,s,e)->>'responseAllowed')::boolean,false);
        if not eligible then candidate_state:='STALE'; end if;
      end if;
      if candidate_state='SELECTABLE' then
        begin
          -- Use the final selection authority, including legacy null/TOTAL/PER_PERSON semantics.
          perform private.assert_application_price_v5(n,c.version_slots,c.version_price);
        exception when sqlstate '22023' or sqlstate 'P0001' then
          if sqlerrm not in ('INVALID_PRICE','FIXED_PRICE_NOT_READY','FIXED_PRICE_MISMATCH',
            'TOTAL_PRICE_REQUIRES_ALL_SLOTS','UNKNOWN_PRICE_BASIS') then raise; end if;
          candidate_state:='STALE';
        end;
      end if;
    end if;
    return next;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_list_my_tasks()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare actor uuid:=auth.uid(); result jsonb;
begin
  if actor is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if not public.rpc_storage_account_open() then raise exception 'ACCOUNT_NOT_OPEN' using errcode='42501'; end if;
  -- The only elevated reader: no caller-supplied account; enumerate ONLY this account's own tasks.
  -- Its document reader omits internal account IDs, close reason and private location data.
  select coalesce(jsonb_agg(public.rpc_read_task(n.id) order by n.created_at desc, n.id desc), '[]'::jsonb)
    into result from public.needs n where n.requester_account_id=actor;
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.selectable_application_count(n public.needs)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare actor uuid:=auth.uid(); actual public.needs; result integer;
begin
  if actor is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if not public.rpc_storage_account_open() then raise exception 'ACCOUNT_NOT_OPEN' using errcode='42501'; end if;
  -- Only the ID is input. Never trust owner/status/price fields in a caller-supplied composite.
  select * into actual from public.needs t where t.id=n.id and t.requester_account_id=actor;
  if not found then return null; end if;
  select count(*)::integer into result from private.need_candidate_states_v5(actual.id) c
    where c.candidate_state='SELECTABLE';
  return result;
end;
$function$
